import jdk.incubator.concurrent.StructuredTaskScope;
import jdk.incubator.concurrent.ScopedValue;

public class OrderService {
    private static final ScopedValue<String> TRANSACTION_ID = ScopedValue.newInstance();

    public OrderResult processOrder(OrderRequest request) throws Exception {
        return ScopedValue.where(TRANSACTION_ID, request.transactionId()).call(() -> {
            try (var scope = new StructuredTaskScope.ShutdownOnFailure()) {
                var userFuture = scope.fork(() -> fetchUser(request.userId()));
                var inventoryFuture = scope.fork(() -> checkInventory(request.itemId()));

                scope.join();          // Join all subtasks
                scope.throwIfFailed(); // Propagate exceptions if any failed

                return new OrderResult(userFuture.get(), inventoryFuture.get());
            }
        });
    }

    private User fetchUser(String userId) { return new User(userId); }
    private Inventory checkInventory(String itemId) { return new Inventory(itemId);
    }
}
